#include <cassert>
#include <iostream>
#include <string>
#include <vector>

std::vector<std::string> trace;
struct Person {
    int id;
    explicit Person(int value) : id(value) { trace.push_back("Person " + std::to_string(value)); }
};
struct Reader : virtual Person {
    Reader() : Person(10) { trace.push_back("Reader"); }
};
struct Volunteer : virtual Person {
    Volunteer() : Person(20) { trace.push_back("Volunteer"); }
};
struct Participant : Reader, Volunteer {
    // 가장 바깥 객체가 공유 가상 기반 Person의 초기화를 책임집니다.
    Participant() : Person(99), Reader(), Volunteer() { trace.push_back("Participant"); }
};
int main() {
    trace.clear();
    Reader alone;
    assert(alone.id == 10);
    assert((trace == std::vector<std::string>{"Person 10", "Reader"}));
    trace.clear();
    Participant both;
    assert((trace == std::vector<std::string>{"Person 99", "Reader", "Volunteer", "Participant"}));
    Person* viaReader = static_cast<Reader*>(&both);
    Person* viaVolunteer = static_cast<Volunteer*>(&both);
    assert(viaReader == viaVolunteer);  // 서로 다른 경로가 같은 기반 객체를 가리킵니다.
    viaReader->id = 42;
    assert(viaVolunteer->id == 42);
    std::cout << "standalone/shared construction and identity passed\n";
}
